'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['updateRoster']);
assert.strictEqual(typeof api.updateRoster, 'function');
const { updateRoster } = api;

assert.deepStrictEqual(updateRoster([], []), []);

const entries = [
  { id: 'a', name: 'Ada', score: 10 },
  { id: 'b', name: '', score: -2 }
];
const changes = [
  { id: 'a', delta: 3 },
  { id: 'b', delta: 2.5 },
  { id: 'a', delta: -1 }
];
const entriesSnapshot = JSON.parse(JSON.stringify(entries));
const changesSnapshot = JSON.parse(JSON.stringify(changes));
const result = updateRoster(entries, changes);
assert.deepStrictEqual(result, [
  { id: 'a', name: 'Ada', score: 12 },
  { id: 'b', name: '', score: 0.5 }
]);
assert.deepStrictEqual(entries, entriesSnapshot);
assert.deepStrictEqual(changes, changesSnapshot);
assert.notStrictEqual(result, entries);
assert.notStrictEqual(result[0], entries[0]);
assert.notStrictEqual(result[1], entries[1]);

const unchanged = updateRoster(entries, []);
assert.deepStrictEqual(unchanged, entries);
assert.notStrictEqual(unchanged, entries);
assert.notStrictEqual(unchanged[0], entries[0]);
assert.notStrictEqual(unchanged[1], entries[1]);

for (const args of [
  [null, []],
  [[], null],
  [[null], []],
  [[{ id: '', name: 'N', score: 1 }], []],
  [[{ id: 'x', name: 7, score: 1 }], []],
  [[{ id: 'x', name: 'N', score: NaN }], []],
  [[{ id: 'x', name: 'N', score: Infinity }], []],
  [[{ id: 'x', name: 'N', score: 1 }], [null]],
  [[{ id: 'x', name: 'N', score: 1 }], [{ id: '', delta: 1 }]],
  [[{ id: 'x', name: 'N', score: 1 }], [{ id: 'x', delta: Infinity }]]
]) {
  assert.throws(() => updateRoster(args[0], args[1]), TypeError);
}

assert.throws(
  () => updateRoster([
    { id: 'x', name: 'One', score: 1 },
    { id: 'x', name: 'Two', score: 2 }
  ], []),
  RangeError
);
assert.throws(
  () => updateRoster([{ id: 'x', name: 'One', score: 1 }], [{ id: 'missing', delta: 1 }]),
  RangeError
);

